// High school intro biology quizzes — hl01 through hl18
export const HS_LIFE_BIO_QUIZZES = [
  { id:'hl01', cat:'Life Sciences', title:`Cell Structure & Function`, diff:'Easy', qs:[
      { q:`Which organelle is known as the "powerhouse of the cell"?`, ch:[`Nucleus`,`Mitochondria`,`Ribosome`,`Golgi apparatus`], ans:1, exp:`Mitochondria generate most of a cell's ATP through cellular respiration, earning them the nickname "powerhouse of the cell."` },
      { q:`What structure controls what enters and exits a cell?`, ch:[`Cell wall`,`Nucleus`,`Cell membrane`,`Cytoplasm`], ans:2, exp:`The cell membrane is selectively permeable, meaning it lets some substances in or out while blocking others.` },
      { q:`Which organelle contains most of a cell's DNA?`, ch:[`Mitochondria`,`Nucleus`,`Ribosome`,`Vacuole`], ans:1, exp:`The nucleus houses the cell's chromosomes and acts as the control center for the cell.` },
      { q:`What is the main job of a ribosome?`, ch:[`Building proteins`,`Storing water`,`Breaking down waste`,`Producing light`], ans:0, exp:`Ribosomes read genetic instructions and link amino acids together to build proteins.` },
      { q:`Which structure is found in plant cells but NOT in animal cells?`, ch:[`Mitochondria`,`Cell membrane`,`Cell wall`,`Nucleus`], ans:2, exp:`Plant cells have a rigid cell wall made of cellulose outside the cell membrane, which animal cells lack.` },
      { q:`What is the jelly-like substance that fills a cell and holds its organelles in place?`, ch:[`Cytoplasm`,`Nucleoplasm`,`Cytoskeleton`,`Chlorophyll`], ans:0, exp:`Cytoplasm is the gel-like fluid inside the cell membrane where organelles are suspended.` },
      { q:`Which organelle packages and ships proteins to their final destination?`, ch:[`Golgi apparatus`,`Lysosome`,`Ribosome`,`Vacuole`], ans:0, exp:`The Golgi apparatus modifies, sorts, and packages proteins into vesicles for transport.` },
      { q:`Lysosomes are best described as a cell's:`, ch:[`Energy factories`,`Digestive and recycling centers`,`Protein factories`,`Light-absorbing structures`], ans:1, exp:`Lysosomes contain enzymes that break down waste, worn-out organelles, and unwanted material.` },
      { q:`Which organelle carries out photosynthesis in plant cells?`, ch:[`Mitochondria`,`Chloroplast`,`Nucleus`,`Vacuole`], ans:1, exp:`Chloroplasts contain chlorophyll and use light energy to make sugar from carbon dioxide and water.` },
      { q:`What is the main function of a plant cell's large central vacuole?`, ch:[`Storing water and keeping the cell rigid`,`Producing ATP`,`Building proteins`,`Copying DNA`], ans:0, exp:`The central vacuole stores water and other materials, and pressure against the cell wall keeps the plant firm.` },
      { q:`Which type of cell lacks a true nucleus?`, ch:[`Animal cell`,`Plant cell`,`Prokaryotic cell`,`Eukaryotic cell`], ans:2, exp:`Prokaryotic cells, such as bacteria, have their DNA floating freely in the cytoplasm instead of inside a nucleus.` },
      { q:`The endoplasmic reticulum covered in ribosomes is called:`, ch:[`Smooth ER`,`Rough ER`,`Golgi body`,`Nuclear envelope`], ans:1, exp:`Rough ER gets its bumpy appearance from the ribosomes attached to it, which build proteins directly into it.` },
    ]
  },
  { id:'hl02', cat:'Life Sciences', title:`Cell Membrane & Transport Basics`, diff:'Easy', qs:[
      { q:`The cell membrane is mainly made of a:`, ch:[`Protein bilayer`,`Phospholipid bilayer`,`Carbohydrate layer`,`Cellulose layer`], ans:1, exp:`The membrane is a double layer of phospholipid molecules with proteins embedded throughout.` },
      { q:`In the phospholipid bilayer, the water-loving (hydrophilic) heads face:`, ch:[`Only the inside of the membrane`,`Away from water`,`Toward the watery environments inside and outside the cell`,`Nowhere in particular`], ans:2, exp:`The hydrophilic heads point outward toward water on both sides, while the water-fearing tails face each other inside.` },
      { q:`What term describes a membrane that lets some substances through but not others?`, ch:[`Impermeable`,`Selectively permeable`,`Fully permeable`,`Rigid`], ans:1, exp:`A selectively permeable membrane controls which molecules can pass, protecting the cell's internal environment.` },
      { q:`Diffusion is the movement of particles from an area of:`, ch:[`Low to high concentration`,`High to low concentration`,`Inside the cell to outside only`,`Equal concentration to unequal`], ans:1, exp:`Particles naturally spread out from where they are crowded to where they are less crowded, without using energy.` },
      { q:`Osmosis specifically refers to the diffusion of:`, ch:[`Proteins`,`Oxygen`,`Water`,`Glucose`], ans:2, exp:`Osmosis is the movement of water across a selectively permeable membrane from an area of high water concentration to low.` },
      { q:`A cell placed in a hypertonic solution (more solute outside than inside) will most likely:`, ch:[`Swell and burst`,`Shrink as water leaves the cell`,`Stay exactly the same`,`Immediately divide`], ans:1, exp:`Water moves out of the cell toward the higher solute concentration outside, causing the cell to shrink.` },
      { q:`Movement of molecules across a membrane that requires the cell to spend energy is called:`, ch:[`Passive transport`,`Active transport`,`Osmosis`,`Simple diffusion`], ans:1, exp:`Active transport moves substances against their concentration gradient, which requires ATP energy.` },
      { q:`Facilitated diffusion differs from simple diffusion because it:`, ch:[`Always requires ATP`,`Uses carrier or channel proteins to help molecules cross`,`Moves substances against the gradient`,`Only happens in plant cells`], ans:1, exp:`Facilitated diffusion still moves molecules down their concentration gradient, but proteins in the membrane help larger or charged molecules pass through.` },
      { q:`A red blood cell placed in pure water (a hypotonic solution) will likely:`, ch:[`Shrink`,`Stay the same size`,`Swell and possibly burst`,`Turn into a different type of cell`], ans:2, exp:`Water rushes into the cell because the inside has a higher solute concentration than the surrounding pure water.` },
      { q:`The process by which a cell engulfs large particles by folding its membrane around them is called:`, ch:[`Osmosis`,`Endocytosis`,`Exocytosis`,`Simple diffusion`], ans:1, exp:`In endocytosis, the cell membrane wraps around material outside the cell and pinches off to bring it inside.` },
      { q:`The process by which a cell releases materials to the outside is called:`, ch:[`Endocytosis`,`Exocytosis`,`Osmosis`,`Active transport`], ans:1, exp:`During exocytosis, a vesicle inside the cell fuses with the cell membrane and releases its contents outward.` },
      { q:`Sodium-potassium pumps moving ions against their concentration gradient are an example of:`, ch:[`Passive transport`,`Facilitated diffusion`,`Active transport`,`Osmosis`], ans:2, exp:`Because the ions move against their natural gradient, the pump must use ATP, making this active transport.` },
    ]
  },
  { id:'hl03', cat:'Life Sciences', title:`Photosynthesis Basics`, diff:'Easy', qs:[
      { q:`Photosynthesis mainly takes place inside which cell structure?`, ch:[`Mitochondria`,`Chloroplast`,`Nucleus`,`Ribosome`], ans:1, exp:`Chloroplasts contain chlorophyll and are the site where plants convert light energy into chemical energy.` },
      { q:`Which green pigment absorbs sunlight to power photosynthesis?`, ch:[`Melanin`,`Chlorophyll`,`Carotene`,`Hemoglobin`], ans:1, exp:`Chlorophyll absorbs mostly red and blue light while reflecting green light, which is why plants appear green.` },
      { q:`What two raw materials do plants need as inputs for photosynthesis?`, ch:[`Glucose and oxygen`,`Carbon dioxide and water`,`Nitrogen and water`,`Oxygen and water`], ans:1, exp:`Plants take in carbon dioxide from the air and water from the soil to build sugar during photosynthesis.` },
      { q:`What two main products does photosynthesis produce?`, ch:[`Carbon dioxide and water`,`Glucose and oxygen`,`Nitrogen and glucose`,`Water and nitrogen`], ans:1, exp:`Photosynthesis produces glucose, which the plant uses for energy, and oxygen, which is released into the air.` },
      { q:`Photosynthesis is powered by energy from:`, ch:[`Sunlight`,`Heat from the soil`,`Chemical reactions in the roots`,`Wind`], ans:0, exp:`Light energy from the sun is captured by chlorophyll and converted into chemical energy stored in glucose.` },
      { q:`Tiny pores on a leaf's surface that let carbon dioxide in and oxygen out are called:`, ch:[`Roots`,`Stomata`,`Xylem`,`Petals`], ans:1, exp:`Stomata are small openings, usually on the underside of leaves, that control gas exchange.` },
      { q:`Most of the oxygen released during photosynthesis comes from splitting apart molecules of:`, ch:[`Carbon dioxide`,`Water`,`Glucose`,`Soil minerals`], ans:1, exp:`During the light reactions, water molecules are split, releasing oxygen as a byproduct.` },
      { q:`Plants are called producers because they:`, ch:[`Eat other organisms for energy`,`Make their own food using light energy`,`Break down dead material for energy`,`Depend entirely on animals for food`], ans:1, exp:`Producers make their own food from sunlight, water, and carbon dioxide instead of eating other organisms.` },
      { q:`The stacks of membranes inside a chloroplast where chlorophyll captures light are called:`, ch:[`Stroma`,`Thylakoids`,`Cristae`,`Ribosomes`], ans:1, exp:`Thylakoids are disc-shaped membranes that house chlorophyll and carry out the light-capturing reactions.` },
      { q:`The sugar-building reactions of photosynthesis (the Calvin cycle) occur in the chloroplast's:`, ch:[`Thylakoid membranes`,`Stroma`,`Outer membrane`,`Nucleus`], ans:1, exp:`The stroma is the fluid-filled space surrounding the thylakoids where carbon dioxide is turned into sugar.` },
      { q:`Which of these is NOT needed as a raw material for photosynthesis?`, ch:[`Sunlight`,`Carbon dioxide`,`Water`,`Oxygen`], ans:3, exp:`Oxygen is a product of photosynthesis, not a raw material the plant takes in to start the process.` },
      { q:`Plants mainly use the glucose they produce during photosynthesis to:`, ch:[`Absorb more sunlight`,`Release oxygen`,`Provide energy and building materials for growth`,`Make chlorophyll`], ans:2, exp:`Glucose is broken down for energy or used to build structures like cell walls, fueling the plant's growth.` },
    ]
  },
  { id:'hl04', cat:'Life Sciences', title:`Cellular Respiration Basics`, diff:'Easy', qs:[
      { q:`Where does most of the ATP-producing process of cellular respiration occur?`, ch:[`Nucleus`,`Mitochondria`,`Ribosome`,`Golgi apparatus`], ans:1, exp:`Mitochondria use oxygen to break down glucose and release large amounts of usable energy as ATP.` },
      { q:`What molecule is the main energy currency produced by cellular respiration?`, ch:[`DNA`,`ATP`,`RNA`,`Glucose`], ans:1, exp:`ATP stores energy in a form cells can quickly use to power their activities.` },
      { q:`What are the reactants (starting materials) of cellular respiration?`, ch:[`Carbon dioxide and water`,`Glucose and oxygen`,`Oxygen and nitrogen`,`Water and glucose`], ans:1, exp:`Cells combine glucose with oxygen to release the energy stored in the glucose molecule.` },
      { q:`What are the main products of cellular respiration?`, ch:[`Glucose and oxygen`,`Carbon dioxide, water, and ATP`,`Nitrogen and ATP`,`Chlorophyll and oxygen`], ans:1, exp:`Breaking down glucose with oxygen releases carbon dioxide and water as waste, along with usable ATP energy.` },
      { q:`Cellular respiration is essentially the reverse of which process?`, ch:[`Photosynthesis`,`Fermentation`,`Mitosis`,`Digestion`], ans:0, exp:`Photosynthesis stores energy by building glucose, while cellular respiration releases that stored energy.` },
      { q:`The first stage of cellular respiration, called glycolysis, takes place in the:`, ch:[`Mitochondria`,`Cytoplasm`,`Nucleus`,`Chloroplast`], ans:1, exp:`Glycolysis breaks glucose into smaller molecules in the cytoplasm before further breakdown in the mitochondria.` },
      { q:`Anaerobic respiration (fermentation) occurs when a cell:`, ch:[`Has plenty of oxygen`,`Lacks sufficient oxygen`,`Has too much glucose`,`Is dividing`], ans:1, exp:`When oxygen is scarce, cells switch to fermentation to keep producing a small amount of energy.` },
      { q:`In human muscle cells, anaerobic respiration produces a buildup of:`, ch:[`Ethanol`,`Lactic acid`,`Carbon dioxide only`,`Oxygen`], ans:1, exp:`During intense exercise, muscle cells ferment glucose into lactic acid when oxygen supply cannot keep up.` },
      { q:`In yeast, fermentation (anaerobic respiration) produces carbon dioxide and:`, ch:[`Lactic acid`,`Ethanol (alcohol)`,`Glucose`,`Oxygen`], ans:1, exp:`Yeast fermentation produces ethanol and carbon dioxide, which is why it is used in baking and brewing.` },
      { q:`Why do living things need cellular respiration?`, ch:[`To make chlorophyll`,`To release usable energy stored in food`,`To absorb sunlight`,`To create new DNA`], ans:1, exp:`Cellular respiration converts the chemical energy in food into ATP that cells can use to function.` },
      { q:`Which gas do humans exhale as a waste product of cellular respiration?`, ch:[`Oxygen`,`Carbon dioxide`,`Nitrogen`,`Hydrogen`], ans:1, exp:`Carbon dioxide is produced when cells break down glucose and is removed from the body through the lungs.` },
      { q:`Compared to anaerobic respiration, aerobic respiration produces:`, ch:[`Much less ATP`,`About the same ATP`,`Much more ATP`,`No ATP at all`], ans:2, exp:`Using oxygen allows cells to fully break down glucose, releasing far more ATP than fermentation alone.` },
    ]
  },
  { id:'hl05', cat:'Life Sciences', title:`DNA & Genes Basics`, diff:'Easy', qs:[
      { q:`What does DNA stand for?`, ch:[`Deoxyribonucleic acid`,`Diribonucleic acid`,`Deoxyribose nuclear acid`,`Dual nucleic acid`], ans:0, exp:`DNA stands for deoxyribonucleic acid, the molecule that stores genetic instructions in living things.` },
      { q:`What shape does a DNA molecule form?`, ch:[`Single strand`,`Double helix`,`Triangle`,`Flat sheet`], ans:1, exp:`DNA is made of two strands twisted around each other, forming a shape known as a double helix.` },
      { q:`DNA is made of repeating units called:`, ch:[`Amino acids`,`Nucleotides`,`Ribosomes`,`Proteins`], ans:1, exp:`Nucleotides, each made of a sugar, phosphate, and nitrogen base, are the building blocks of DNA.` },
      { q:`Which base pairs with adenine (A) in DNA?`, ch:[`Guanine`,`Cytosine`,`Thymine`,`Uracil`], ans:2, exp:`Adenine always pairs with thymine in DNA, held together by hydrogen bonds.` },
      { q:`Which base pairs with guanine (G) in DNA?`, ch:[`Adenine`,`Cytosine`,`Thymine`,`Uracil`], ans:1, exp:`Guanine always pairs with cytosine in DNA, forming one of the rungs of the double helix.` },
      { q:`A gene is best defined as:`, ch:[`An entire chromosome`,`A segment of DNA that codes for a specific trait or protein`,`A type of protein`,`The nucleus of a cell`], ans:1, exp:`A gene is a specific stretch of DNA that contains the instructions for making a particular protein or trait.` },
      { q:`Where is most of a human cell's DNA located?`, ch:[`Mitochondria`,`Nucleus`,`Ribosome`,`Cell membrane`], ans:1, exp:`The nucleus houses nearly all of a cell's DNA, organized into chromosomes.` },
      { q:`DNA carries genetic information in the form of a sequence of:`, ch:[`Amino acids`,`Sugars`,`Bases (A, T, C, G)`,`Fatty acids`], ans:2, exp:`The order of the four bases along a DNA strand encodes the instructions for building proteins.` },
      { q:`Chromosomes are made of DNA tightly wound around proteins called:`, ch:[`Histones`,`Enzymes`,`Hormones`,`Antibodies`], ans:0, exp:`Histone proteins act like spools that DNA wraps around, helping it pack tightly into the nucleus.` },
      { q:`How many chromosomes are normally found in each human body cell?`, ch:[`23`,`46`,`92`,`12`], ans:1, exp:`Human body cells normally contain 46 chromosomes, arranged as 23 pairs.` },
      { q:`RNA differs from DNA in that RNA contains which base instead of thymine?`, ch:[`Adenine`,`Guanine`,`Cytosine`,`Uracil`], ans:3, exp:`RNA uses uracil in place of thymine as one of its four nitrogen bases.` },
      { q:`The process of copying DNA before a cell divides is called:`, ch:[`Transcription`,`Translation`,`Replication`,`Mutation`], ans:2, exp:`DNA replication makes an identical copy of a cell's DNA so each new cell gets a full set of genetic instructions.` },
    ]
  },
  { id:'hl06', cat:'Life Sciences', title:`Mendelian Genetics & Punnett Squares`, diff:'Medium', qs:[
      { q:`Who is known as the "father of genetics" for his experiments on pea plants?`, ch:[`Charles Darwin`,`Gregor Mendel`,`James Watson`,`Rosalind Franklin`], ans:1, exp:`Gregor Mendel's 19th-century pea plant experiments revealed the basic patterns of how traits are inherited.` },
      { q:`An organism's observable physical traits are called its:`, ch:[`Genotype`,`Phenotype`,`Allele`,`Karyotype`], ans:1, exp:`Phenotype refers to the traits you can actually see or measure, like eye color or height.` },
      { q:`The genetic makeup of an organism, meaning its combination of alleles, is called its:`, ch:[`Phenotype`,`Genotype`,`Species`,`Trait`], ans:1, exp:`Genotype describes the specific alleles an organism carries for a given gene.` },
      { q:`If a genotype is written as Tt, this organism is considered:`, ch:[`Homozygous dominant`,`Homozygous recessive`,`Heterozygous`,`Haploid`], ans:2, exp:`Heterozygous means the organism has two different alleles for that gene, one dominant and one recessive.` },
      { q:`A dominant allele is one that:`, ch:[`Is only expressed when two copies are present`,`Is expressed whenever at least one copy is present`,`Never affects the phenotype`,`Only appears in females`], ans:1, exp:`A dominant allele masks the effect of a recessive allele, so just one copy is enough to show up in the phenotype.` },
      { q:`In a Punnett square cross of Tt x Tt, what fraction of offspring is expected to show the recessive trait?`, ch:[`1/4`,`1/2`,`3/4`,`All of them`], ans:0, exp:`Crossing two heterozygotes gives a 1:2:1 genotype ratio, meaning 1 out of 4 offspring is homozygous recessive.` },
      { q:`If a homozygous dominant parent (TT) is crossed with a homozygous recessive parent (tt), what genotype will all offspring have?`, ch:[`TT`,`tt`,`Tt`,`A mix of all three`], ans:2, exp:`Each parent can only contribute one type of allele, so every offspring receives one T and one t, making them Tt.` },
      { q:`A recessive trait will only appear in an organism's phenotype when:`, ch:[`At least one dominant allele is present`,`Both alleles present are recessive`,`The organism is heterozygous`,`The trait skips a generation`], ans:1, exp:`Because a dominant allele would mask it, a recessive trait only shows up when both alleles are recessive.` },
      { q:`In humans, imagine brown eyes (B) are dominant over blue eyes (b). A cross between Bb and bb parents produces offspring in what ratio of brown to blue eyes?`, ch:[`3:1`,`1:1`,`1:3`,`All brown`], ans:1, exp:`Half the offspring inherit Bb (brown) and half inherit bb (blue), giving a 1:1 ratio.` },
      { q:`What term describes the different versions of a gene, such as B and b?`, ch:[`Alleles`,`Chromosomes`,`Genotypes`,`Genomes`], ans:0, exp:`Alleles are alternate forms of the same gene that can produce different versions of a trait.` },
      { q:`A cross that studies the inheritance of only one trait, such as seed color, is called a:`, ch:[`Dihybrid cross`,`Monohybrid cross`,`Test cross`,`Backcross`], ans:1, exp:`A monohybrid cross tracks how a single trait is passed from parents to offspring.` },
      { q:`In incomplete dominance, a cross between red-flowered (RR) and white-flowered (WW) plants produces offspring that are:`, ch:[`All red`,`All white`,`Pink, a blend of both colors`,`Spotted red and white`], ans:2, exp:`With incomplete dominance, neither allele fully masks the other, so the heterozygous offspring show a blended phenotype.` },
    ]
  },
  { id:'hl07', cat:'Life Sciences', title:`Mitosis vs Meiosis`, diff:'Medium', qs:[
      { q:`What is the main purpose of mitosis?`, ch:[`To produce sperm and egg cells`,`To produce two genetically identical daughter cells for growth and repair`,`To shuffle genetic material for variation`,`To reduce chromosome number by half`], ans:1, exp:`Mitosis allows an organism to grow, replace damaged cells, and repair tissue by making identical copies of a cell.` },
      { q:`What is the main purpose of meiosis?`, ch:[`To repair damaged skin`,`To produce gametes (sex cells) with half the normal chromosome number`,`To produce identical body cells`,`To digest nutrients`], ans:1, exp:`Meiosis creates sperm and egg cells, each with half the usual number of chromosomes.` },
      { q:`How many daughter cells result from one round of mitosis?`, ch:[`1`,`2`,`4`,`8`], ans:1, exp:`Mitosis splits one parent cell into two genetically identical daughter cells.` },
      { q:`How many daughter cells result from meiosis, starting with one cell?`, ch:[`1`,`2`,`4`,`8`], ans:2, exp:`Meiosis involves two rounds of division, producing four haploid daughter cells from one starting cell.` },
      { q:`Are the daughter cells produced by mitosis genetically identical to the parent cell?`, ch:[`Yes`,`No, they are completely different`,`Only sometimes`,`Only in plants`], ans:0, exp:`Mitosis copies the parent cell's DNA exactly, so the daughter cells are genetically identical clones.` },
      { q:`Are the cells produced by meiosis genetically identical to each other?`, ch:[`Yes, always identical`,`No, they are genetically different from one another`,`Only in males`,`Only in females`], ans:1, exp:`Crossing over and random assortment during meiosis shuffle genes, making each resulting cell genetically unique.` },
      { q:`Human body (somatic) cells are described as diploid, meaning they have:`, ch:[`One set of chromosomes`,`Two sets of chromosomes`,`Three sets of chromosomes`,`No chromosomes`], ans:1, exp:`Diploid cells contain two complete sets of chromosomes, one inherited from each parent.` },
      { q:`Human gametes, such as sperm and egg cells, are described as haploid, meaning they have:`, ch:[`One full set of chromosomes`,`Two full sets of chromosomes`,`Four full sets of chromosomes`,`No genetic material`], ans:0, exp:`Haploid cells carry only one set of chromosomes, half the number found in body cells.` },
      { q:`During which phase of mitosis do chromosomes line up in the middle of the cell?`, ch:[`Prophase`,`Metaphase`,`Anaphase`,`Telophase`], ans:1, exp:`In metaphase, chromosomes align along the cell's equator before being pulled apart.` },
      { q:`Crossing over, which increases genetic variation, mainly occurs during:`, ch:[`Mitosis`,`Meiosis`,`Fertilization`,`Interphase`], ans:1, exp:`During meiosis, homologous chromosomes exchange segments of DNA, creating new combinations of alleles.` },
      { q:`Which process is mainly responsible for growth and healing of tissues in the body?`, ch:[`Meiosis`,`Mitosis`,`Fertilization`,`Fermentation`], ans:1, exp:`Mitosis produces new identical cells that allow tissues to grow and heal wounds.` },
      { q:`Fertilization restores the diploid chromosome number by combining:`, ch:[`Two diploid cells`,`A haploid sperm and a haploid egg`,`Two haploid sperm cells`,`Two somatic cells`], ans:1, exp:`When a haploid sperm fertilizes a haploid egg, their chromosomes combine to form a diploid cell.` },
    ]
  },
  { id:'hl08', cat:'Life Sciences', title:`Evolution & Natural Selection Basics`, diff:'Easy', qs:[
      { q:`Who is best known for proposing the theory of evolution by natural selection?`, ch:[`Gregor Mendel`,`Charles Darwin`,`Louis Pasteur`,`Carl Linnaeus`], ans:1, exp:`Charles Darwin developed the theory of natural selection after studying species diversity, notably on the Galapagos Islands.` },
      { q:`Natural selection favors individuals with traits that:`, ch:[`Are the largest in the population`,`Increase survival and reproduction in their environment`,`Are the most colorful`,`Appear most often regardless of usefulness`], ans:1, exp:`Traits that help an organism survive and reproduce are more likely to be passed on to future generations.` },
      { q:`The phrase "survival of the fittest" refers to:`, ch:[`Only the physically strongest organisms surviving`,`Organisms best suited to their environment being more likely to survive and reproduce`,`All organisms surviving equally`,`Organisms that migrate the farthest`], ans:1, exp:`"Fittest" means best adapted to the environment, not necessarily the biggest or strongest.` },
      { q:`What is the original source of new genetic variation in a population?`, ch:[`Mutations`,`Natural selection`,`Migration only`,`Camouflage`], ans:0, exp:`Random changes in DNA, called mutations, create new alleles that can introduce variation into a population.` },
      { q:`Structures like a human arm and a bird wing, which share a common ancestor, are called:`, ch:[`Analogous structures`,`Homologous structures`,`Vestigial structures`,`Convergent structures`], ans:1, exp:`Homologous structures have similar underlying bone patterns because the species share an evolutionary ancestor.` },
      { q:`Structures like a butterfly wing and a bird wing, which look similar but evolved independently, are called:`, ch:[`Homologous structures`,`Vestigial structures`,`Analogous structures`,`Ancestral structures`], ans:2, exp:`Analogous structures serve a similar function but did not evolve from a shared ancestor.` },
      { q:`Vestigial structures, like the human appendix, are best described as:`, ch:[`New structures that just appeared`,`Reduced structures that had a function in ancestors but are less useful today`,`Structures that will become larger over time`,`Structures unique to a single individual`], ans:1, exp:`Vestigial structures are remnants of features that served a purpose in an organism's ancestors.` },
      { q:`What term describes a population's traits changing gradually over many generations?`, ch:[`Mutation`,`Evolution`,`Reproduction`,`Classification`], ans:1, exp:`Evolution is the process by which populations change genetically over time.` },
      { q:`The peppered moth example, where dark moths became more common during periods of industrial pollution, illustrates:`, ch:[`Random genetic drift only`,`Natural selection favoring camouflage that matched the environment`,`Artificial selection by scientists`,`A lack of any selective pressure`], ans:1, exp:`Darker moths were better camouflaged against soot-darkened trees, so they survived and reproduced more than lighter moths.` },
      { q:`Artificial selection differs from natural selection because:`, ch:[`It happens only in the wild`,`Humans choose which traits are passed on, rather than the environment`,`It cannot change a species over time`,`It only applies to plants`], ans:1, exp:`In artificial selection, humans breed organisms for chosen traits instead of nature selecting them.` },
      { q:`A species of bacteria developing resistance to an antibiotic over time is an example of:`, ch:[`Artificial selection`,`Natural selection`,`Vestigial adaptation`,`Classification`], ans:1, exp:`Bacteria that happen to survive the antibiotic reproduce, passing on resistance genes to future generations.` },
      { q:`Fossils provide evidence for evolution mainly by:`, ch:[`Proving all species appeared at the same time`,`Showing how species have changed over long periods of time`,`Showing that species never change`,`Proving that only extinct species existed`], ans:1, exp:`Fossils found in different rock layers show a record of how species have changed and diversified over millions of years.` },
    ]
  },
  { id:'hl09', cat:'Life Sciences', title:`Classification & Taxonomy`, diff:'Easy', qs:[
      { q:`Who developed the modern system of naming organisms with two-part scientific names?`, ch:[`Charles Darwin`,`Carl Linnaeus`,`Gregor Mendel`,`Charles Lyell`], ans:1, exp:`Carl Linnaeus created the naming system still used today to classify and name living things.` },
      { q:`What is the two-part naming system for species called?`, ch:[`Binomial nomenclature`,`Dichotomous naming`,`Taxonomic ranking`,`Cladistic naming`], ans:0, exp:`Binomial nomenclature gives each species a two-part scientific name made of its genus and species.` },
      { q:`In the scientific name Homo sapiens, what does "Homo" represent?`, ch:[`The species`,`The genus`,`The family`,`The kingdom`], ans:1, exp:`The first word in a scientific name is always the genus; the second word is the specific species.` },
      { q:`Which list correctly orders taxonomic ranks from broadest to most specific?`, ch:[`Kingdom, Phylum, Class, Order, Family, Genus, Species`,`Species, Genus, Family, Order, Class, Phylum, Kingdom`,`Phylum, Kingdom, Class, Order, Family, Genus, Species`,`Kingdom, Class, Phylum, Order, Family, Genus, Species`], ans:0, exp:`Taxonomic ranks go from the broadest group, Kingdom, down to the most specific group, Species.` },
      { q:`Which of these is NOT one of the recognized kingdoms of life?`, ch:[`Animalia`,`Plantae`,`Mammalia`,`Fungi`], ans:2, exp:`Mammalia is a class of animals, not a kingdom — Animalia, Plantae, and Fungi are examples of actual kingdoms.` },
      { q:`Which kingdom includes organisms like bacteria that lack a nucleus?`, ch:[`Animalia`,`Plantae`,`Monera or Bacteria`,`Fungi`], ans:2, exp:`Bacteria are prokaryotes and are grouped separately from organisms whose cells have a nucleus.` },
      { q:`Members of the same species are generally defined by their ability to:`, ch:[`Live in the same habitat`,`Interbreed and produce fertile offspring`,`Eat the same food`,`Look identical`], ans:1, exp:`A species is typically defined as a group of organisms that can breed together and produce fertile offspring.` },
      { q:`Which domain includes bacteria?`, ch:[`Domain Eukarya`,`Domain Bacteria`,`Domain Animalia`,`Domain Fungi`], ans:1, exp:`Domain Bacteria is one of the three domains of life, alongside Archaea and Eukarya.` },
      { q:`Fungi, such as mushrooms, are classified separately from plants mainly because fungi:`, ch:[`Can photosynthesize like plants`,`Cannot make their own food and have different cell walls`,`Have no cell walls at all`,`Are identical to animals`], ans:1, exp:`Unlike plants, fungi cannot perform photosynthesis and instead absorb nutrients from their surroundings.` },
      { q:`A dichotomous key is a tool used to:`, ch:[`Measure an organism's size`,`Identify organisms by making a series of either/or choices`,`Count chromosomes`,`Determine an organism's age`], ans:1, exp:`A dichotomous key guides you through paired statements, narrowing down an organism's identity step by step.` },
      { q:`Which taxonomic rank is more specific: Family or Genus?`, ch:[`Family`,`Genus`,`They are equally specific`,`Neither is a taxonomic rank`], ans:1, exp:`Genus is a smaller, more specific grouping than Family, which contains multiple related genera.` },
      { q:`Scientific names are conventionally written:`, ch:[`In all capital letters`,`Italicized, with the genus capitalized and species lowercase`,`In quotation marks only`,`Without any formatting rules`], ans:1, exp:`By convention, scientific names are italicized (or underlined when handwritten), with only the genus capitalized.` },
    ]
  },
  { id:'hl10', cat:'Life Sciences', title:`Ecosystems & Food Chains`, diff:'Easy', qs:[
      { q:`In a food chain, organisms that make their own food are called:`, ch:[`Consumers`,`Producers`,`Decomposers`,`Predators`], ans:1, exp:`Producers, such as plants and algae, create their own food through photosynthesis.` },
      { q:`Organisms that must eat other organisms to get energy are called:`, ch:[`Producers`,`Consumers`,`Autotrophs`,`Decomposers`], ans:1, exp:`Consumers cannot make their own food, so they obtain energy by eating other organisms.` },
      { q:`An organism that eats only plants is called a(n):`, ch:[`Carnivore`,`Herbivore`,`Omnivore`,`Decomposer`], ans:1, exp:`Herbivores get their energy solely from eating plant material.` },
      { q:`An organism that eats both plants and animals is called a(n):`, ch:[`Herbivore`,`Carnivore`,`Omnivore`,`Producer`], ans:2, exp:`Omnivores have a varied diet that includes both plant and animal matter.` },
      { q:`Organisms that break down dead organisms and recycle nutrients back into the ecosystem are called:`, ch:[`Producers`,`Herbivores`,`Decomposers`,`Predators`], ans:2, exp:`Decomposers, like fungi and many bacteria, break down dead material and return nutrients to the soil.` },
      { q:`In a food chain, energy generally flows:`, ch:[`From producers to consumers, decreasing at each level`,`Equally between all organisms`,`From consumers back to producers`,`Only within a single species`], ans:0, exp:`Energy enters an ecosystem through producers and flows to consumers, with some lost as heat at each step.` },
      { q:`At each step up a food chain, roughly how much energy is passed on to the next level?`, ch:[`About 90%`,`About 50%`,`About 10%`,`About 100%`], ans:2, exp:`Only about 10% of energy is typically transferred to the next trophic level; the rest is lost mostly as heat.` },
      { q:`A food web differs from a food chain because a food web:`, ch:[`Shows only one path of energy flow`,`Shows multiple interconnected feeding relationships`,`Only includes producers`,`Never includes decomposers`], ans:1, exp:`A food web combines many overlapping food chains to show the complex feeding relationships in an ecosystem.` },
      { q:`If a primary consumer population suddenly declines, what most likely happens to the producer population it eats?`, ch:[`It tends to increase`,`It tends to decrease`,`It stays exactly the same`,`It disappears immediately`], ans:0, exp:`With fewer consumers grazing on them, producers face less pressure and their population tends to grow.` },
      { q:`Top predators at the end of a food chain, with few or no natural enemies, are also called:`, ch:[`Primary consumers`,`Producers`,`Apex or tertiary consumers`,`Decomposers`], ans:2, exp:`Apex predators sit at the top of the food chain and are rarely preyed upon by other animals.` },
      { q:`Which trophic level in an ecosystem typically has the greatest amount of available energy?`, ch:[`Producers`,`Primary consumers`,`Secondary consumers`,`Tertiary consumers`], ans:0, exp:`Producers capture the most energy directly from the sun, so they sit at the base with the most energy available.` },
      { q:`A relationship in which both organisms benefit, like bees pollinating flowers, is called:`, ch:[`Parasitism`,`Predation`,`Mutualism`,`Competition`], ans:2, exp:`In mutualism, both species gain something helpful from the interaction, such as food and pollination services.` },
    ]
  },
  { id:'hl11', cat:'Life Sciences', title:`Biomes of the World`, diff:'Easy', qs:[
      { q:`Which biome has very low rainfall and large temperature swings, and is home to cacti and reptiles?`, ch:[`Tundra`,`Desert`,`Rainforest`,`Taiga`], ans:1, exp:`Deserts receive very little precipitation, and many desert organisms are adapted to conserve water.` },
      { q:`Which biome has permanently frozen subsoil (permafrost) and low-growing plants like mosses and lichens?`, ch:[`Desert`,`Savanna`,`Tundra`,`Rainforest`], ans:2, exp:`The tundra's cold climate keeps a layer of soil frozen year-round, limiting plant growth to small, hardy species.` },
      { q:`Which biome has the greatest biodiversity of any land biome and receives the most annual rainfall?`, ch:[`Tundra`,`Desert`,`Tropical rainforest`,`Grassland`], ans:2, exp:`Warm temperatures and heavy year-round rainfall in tropical rainforests support an enormous variety of species.` },
      { q:`Grasslands with scattered trees, home to animals like lions and zebras, are called:`, ch:[`Taiga`,`Savanna`,`Tundra`,`Chaparral`], ans:1, exp:`Savannas are warm grasslands with a distinct wet and dry season and scattered trees across open plains.` },
      { q:`A biome with cold winters, mild summers, and vast forests of coniferous evergreen trees is called:`, ch:[`Taiga (boreal forest)`,`Tropical rainforest`,`Desert`,`Savanna`], ans:0, exp:`The taiga is the largest land biome, stretching across northern regions and dominated by conifer trees.` },
      { q:`Temperate deciduous forests are best characterized by:`, ch:[`Trees that lose their leaves seasonally and four distinct seasons`,`No rainfall at all`,`Permanently frozen ground`,`Constant year-round heat`], ans:0, exp:`Deciduous forests experience four seasons, and their trees shed leaves in fall to conserve energy through winter.` },
      { q:`Which factor most determines which biome exists in a given region?`, ch:[`Soil color`,`Climate (temperature and precipitation)`,`Number of predators present`,`Distance from the equator only`], ans:1, exp:`Long-term patterns of temperature and rainfall are the main forces that shape which plants and animals live in an area.` },
      { q:`Coral reefs are typically found within which larger biome type?`, ch:[`Freshwater`,`Marine (ocean)`,`Desert`,`Tundra`], ans:1, exp:`Coral reefs form in shallow, warm saltwater environments, making them part of the marine biome.` },
      { q:`Which of these is an example of a freshwater biome?`, ch:[`Coral reef`,`Ocean`,`Lake`,`Savanna`], ans:2, exp:`Lakes, rivers, and ponds are freshwater biomes, distinct from the salty water found in oceans.` },
      { q:`In which biome would you most expect to find animals like polar bears and arctic foxes?`, ch:[`Tundra`,`Desert`,`Rainforest`,`Savanna`], ans:0, exp:`Polar bears and arctic foxes are adapted to the cold, harsh conditions of the arctic tundra.` },
      { q:`Grassland biomes in central North America are often called:`, ch:[`Steppes`,`Prairies`,`Pampas`,`Savannas`], ans:1, exp:`North American grasslands are commonly known as prairies, historically home to bison and tall grasses.` },
      { q:`Why do tundra biomes support relatively few tree species?`, ch:[`The soil is too rocky everywhere`,`Short growing seasons and frozen soil limit tree growth`,`There is too much rainfall`,`Trees cannot survive any cold at all`], ans:1, exp:`Cold temperatures, frozen subsoil, and a very short growing season make it difficult for trees to establish roots.` },
    ]
  },
  { id:'hl12', cat:'Life Sciences', title:`Human Body Systems Overview`, diff:'Easy', qs:[
      { q:`Which system is responsible for pumping blood throughout the body?`, ch:[`Digestive system`,`Circulatory system`,`Respiratory system`,`Skeletal system`], ans:1, exp:`The circulatory system, powered by the heart, moves blood carrying oxygen and nutrients throughout the body.` },
      { q:`Which system breaks down food into nutrients the body can absorb and use?`, ch:[`Digestive system`,`Nervous system`,`Skeletal system`,`Endocrine system`], ans:0, exp:`The digestive system processes food into smaller molecules that the body can absorb into the bloodstream.` },
      { q:`Which system brings oxygen into the body and removes carbon dioxide?`, ch:[`Circulatory system`,`Muscular system`,`Respiratory system`,`Excretory system`], ans:2, exp:`The respiratory system, including the lungs, exchanges oxygen and carbon dioxide with the air.` },
      { q:`Which system provides structural support and protects internal organs using bones?`, ch:[`Skeletal system`,`Muscular system`,`Nervous system`,`Digestive system`], ans:0, exp:`The skeletal system forms a framework that supports the body and shields organs like the brain and heart.` },
      { q:`Which system controls the body using electrical signals sent through nerves?`, ch:[`Endocrine system`,`Nervous system`,`Circulatory system`,`Immune system`], ans:1, exp:`The nervous system uses electrical and chemical signals to quickly control body functions and reactions.` },
      { q:`Which system produces hormones that regulate body functions over time?`, ch:[`Nervous system`,`Endocrine system`,`Muscular system`,`Skeletal system`], ans:1, exp:`The endocrine system releases hormones into the bloodstream to regulate processes like growth and metabolism.` },
      { q:`Which system defends the body against pathogens and disease?`, ch:[`Immune system`,`Muscular system`,`Skeletal system`,`Digestive system`], ans:0, exp:`The immune system identifies and fights off harmful invaders like bacteria and viruses.` },
      { q:`Which system filters waste from the blood and produces urine?`, ch:[`Digestive system`,`Excretory (urinary) system`,`Respiratory system`,`Skeletal system`], ans:1, exp:`The excretory system, centered on the kidneys, removes waste products from the blood and forms urine.` },
      { q:`Which system allows the body to move by contracting and relaxing?`, ch:[`Muscular system`,`Nervous system`,`Endocrine system`,`Immune system`], ans:0, exp:`Muscles contract and relax to move bones and body parts, enabling all forms of physical movement.` },
      { q:`Organs like the skin, hair, and nails are part of which body system?`, ch:[`Skeletal system`,`Muscular system`,`Integumentary system`,`Endocrine system`], ans:2, exp:`The integumentary system includes the skin and its related structures, which protect the body from the outside environment.` },
      { q:`Which system is responsible for producing offspring?`, ch:[`Reproductive system`,`Excretory system`,`Respiratory system`,`Immune system`], ans:0, exp:`The reproductive system contains the organs needed to produce offspring and continue a species.` },
      { q:`Which statement best describes how body systems work together?`, ch:[`Each system works completely independently of the others`,`They interact and depend on each other to maintain homeostasis`,`Only one system is active at a time`,`Systems only interact during illness`], ans:1, exp:`Body systems constantly cooperate, such as the respiratory and circulatory systems working together to deliver oxygen.` },
    ]
  },
  { id:'hl13', cat:'Life Sciences', title:`The Digestive System`, diff:'Medium', qs:[
      { q:`Digestion begins in the mouth, where an enzyme in saliva starts breaking down:`, ch:[`Proteins`,`Fats`,`Starches (carbohydrates)`,`Vitamins`], ans:2, exp:`Salivary amylase in the mouth begins breaking starches down into simpler sugars before you even swallow.` },
      { q:`The tube-like structure connecting the mouth to the stomach is called the:`, ch:[`Trachea`,`Esophagus`,`Pharynx only`,`Bronchus`], ans:1, exp:`The esophagus uses muscle contractions to push swallowed food down into the stomach.` },
      { q:`Which organ churns food and mixes it with acid and enzymes to begin protein digestion?`, ch:[`Liver`,`Small intestine`,`Stomach`,`Pancreas`], ans:2, exp:`The stomach's muscular walls churn food while stomach acid and the enzyme pepsin start breaking down proteins.` },
      { q:`Most nutrient absorption into the bloodstream occurs in the:`, ch:[`Stomach`,`Small intestine`,`Large intestine`,`Esophagus`], ans:1, exp:`The small intestine's large surface area, lined with villi, makes it the main site of nutrient absorption.` },
      { q:`What is the main function of the large intestine?`, ch:[`Digest proteins`,`Absorb water and form solid waste`,`Produce bile`,`Store food before digestion`], ans:1, exp:`The large intestine absorbs remaining water from digested material and compacts the leftover waste.` },
      { q:`Bile, which helps digest fats, is produced by the:`, ch:[`Stomach`,`Liver`,`Pancreas`,`Small intestine`], ans:1, exp:`The liver produces bile, which is stored in the gallbladder and released to help break down fats.` },
      { q:`Which organ produces enzymes that help digest food and also produces the hormone insulin?`, ch:[`Liver`,`Gallbladder`,`Pancreas`,`Stomach`], ans:2, exp:`The pancreas releases digestive enzymes into the small intestine and produces insulin to regulate blood sugar.` },
      { q:`Peristalsis refers to:`, ch:[`The chemical breakdown of food by acid`,`Wave-like muscle contractions that push food through the digestive tract`,`The absorption of nutrients into blood`,`The storage of bile in the gallbladder`], ans:1, exp:`Peristalsis is the squeezing motion of muscles that moves food along the esophagus and intestines.` },
      { q:`The stomach's highly acidic environment mainly helps to:`, ch:[`Absorb vitamins`,`Break down food and kill harmful bacteria`,`Store water for the body`,`Produce red blood cells`], ans:1, exp:`Stomach acid helps activate digestive enzymes and destroys many harmful microbes that enter with food.` },
      { q:`Villi, the tiny finger-like projections lining the small intestine, function to:`, ch:[`Produce stomach acid`,`Increase surface area for nutrient absorption`,`Break food into smaller pieces mechanically`,`Store undigested waste`], ans:1, exp:`Villi greatly increase the surface area of the small intestine, allowing more nutrients to be absorbed efficiently.` },
      { q:`Undigested waste material is eliminated from the body through the:`, ch:[`Esophagus`,`Stomach`,`Rectum and anus`,`Liver`], ans:2, exp:`After water is absorbed in the large intestine, remaining solid waste is stored and eliminated through the rectum and anus.` },
      { q:`Which nutrient does the enzyme pepsin, found in the stomach, mainly break down?`, ch:[`Carbohydrates`,`Proteins`,`Fats`,`Vitamins`], ans:1, exp:`Pepsin is a protein-digesting enzyme activated by the stomach's acidic environment.` },
    ]
  },
  { id:'hl14', cat:'Life Sciences', title:`The Circulatory System`, diff:'Medium', qs:[
      { q:`How many chambers does the human heart have?`, ch:[`2`,`3`,`4`,`6`], ans:2, exp:`The heart has four chambers: two upper atria and two lower ventricles.` },
      { q:`Which blood vessels carry blood away from the heart?`, ch:[`Veins`,`Arteries`,`Capillaries`,`Venules`], ans:1, exp:`Arteries carry blood away from the heart, usually under higher pressure than veins.` },
      { q:`Which blood vessels carry blood back toward the heart?`, ch:[`Arteries`,`Veins`,`Capillaries`,`Arterioles`], ans:1, exp:`Veins return blood to the heart and often contain valves to prevent blood from flowing backward.` },
      { q:`Where does gas and nutrient exchange between blood and body tissues mainly occur?`, ch:[`Arteries`,`Veins`,`Capillaries`,`The heart`], ans:2, exp:`Capillaries have extremely thin walls, allowing oxygen, carbon dioxide, and nutrients to pass through easily.` },
      { q:`Which side of the heart pumps oxygen-rich blood out to the rest of the body?`, ch:[`Right side`,`Left side`,`Both sides equally`,`Neither side`], ans:1, exp:`The left side of the heart receives oxygen-rich blood from the lungs and pumps it out to the body.` },
      { q:`Which side of the heart pumps oxygen-poor blood to the lungs?`, ch:[`Left side`,`Right side`,`Both sides equally`,`Neither side`], ans:1, exp:`The right side of the heart collects oxygen-poor blood from the body and sends it to the lungs to pick up oxygen.` },
      { q:`Red blood cells mainly function to:`, ch:[`Fight infections`,`Carry oxygen throughout the body`,`Clot blood`,`Produce hormones`], ans:1, exp:`Red blood cells contain hemoglobin, a protein that binds oxygen and carries it to body tissues.` },
      { q:`White blood cells mainly function to:`, ch:[`Carry oxygen`,`Fight infection and defend the body`,`Form blood clots`,`Transport hormones`], ans:1, exp:`White blood cells are part of the immune system and help the body fight off pathogens.` },
      { q:`Platelets are primarily responsible for:`, ch:[`Carrying carbon dioxide`,`Fighting viruses`,`Blood clotting`,`Producing plasma`], ans:2, exp:`Platelets clump together at a wound site and help form clots to stop bleeding.` },
      { q:`The liquid portion of blood that carries cells, nutrients, and waste is called:`, ch:[`Plasma`,`Serum only`,`Hemoglobin`,`Marrow`], ans:0, exp:`Plasma is the yellowish liquid part of blood that transports blood cells, nutrients, and dissolved substances.` },
      { q:`Blood pressure is a measure of:`, ch:[`The number of red blood cells in the body`,`The force blood exerts against the walls of arteries`,`How fast the heart beats`,`The amount of oxygen in the blood`], ans:1, exp:`Blood pressure measures how hard blood pushes against artery walls as the heart pumps.` },
      { q:`Which type of blood vessel has thick, muscular walls to withstand high pressure from the heart?`, ch:[`Veins`,`Capillaries`,`Arteries`,`Venules`], ans:2, exp:`Arteries have thick, elastic, muscular walls because they carry blood under much higher pressure than veins.` },
    ]
  },
  { id:'hl15', cat:'Life Sciences', title:`The Respiratory System`, diff:'Medium', qs:[
      { q:`Air enters the body primarily through the:`, ch:[`Esophagus`,`Nose and mouth`,`Stomach`,`Diaphragm`], ans:1, exp:`Air is normally taken in through the nose or mouth before traveling down into the lungs.` },
      { q:`The tube that carries air from the throat down toward the lungs is called the:`, ch:[`Esophagus`,`Trachea`,`Bronchiole`,`Alveolus`], ans:1, exp:`The trachea, or windpipe, is a rigid tube that channels air from the throat into the chest.` },
      { q:`The trachea branches into two tubes, each leading into a lung, called the:`, ch:[`Bronchi`,`Alveoli`,`Capillaries`,`Villi`], ans:0, exp:`The trachea splits into the left and right bronchus, together called bronchi, which lead into each lung.` },
      { q:`Gas exchange, where oxygen moves in and carbon dioxide moves out, occurs in tiny air sacs called:`, ch:[`Bronchioles`,`Alveoli`,`Trachea`,`Larynx`], ans:1, exp:`Alveoli are the small, thin-walled sacs at the ends of the airways where gases are exchanged with the blood.` },
      { q:`The dome-shaped muscle below the lungs that contracts and relaxes to help you breathe is the:`, ch:[`Diaphragm`,`Trachea`,`Esophagus`,`Larynx`], ans:0, exp:`The diaphragm changes the volume of the chest cavity, driving air in and out of the lungs.` },
      { q:`When you inhale, the diaphragm:`, ch:[`Relaxes and moves upward`,`Contracts and moves downward, expanding the chest cavity`,`Stops moving completely`,`Pushes air directly out of the lungs`], ans:1, exp:`As the diaphragm contracts and flattens downward, it enlarges the chest cavity, drawing air into the lungs.` },
      { q:`Oxygen from the alveoli diffuses into the blood and binds to which molecule in red blood cells?`, ch:[`Insulin`,`Hemoglobin`,`Collagen`,`Antibody`], ans:1, exp:`Hemoglobin in red blood cells binds oxygen so it can be transported throughout the body.` },
      { q:`Carbon dioxide, which the respiratory system helps remove, is mainly a waste product of:`, ch:[`Digestion`,`Cellular respiration`,`Photosynthesis`,`Blood clotting`], ans:1, exp:`Cells produce carbon dioxide as a byproduct while breaking down glucose for energy, and the lungs remove it from the body.` },
      { q:`The epiglottis's main job is to:`, ch:[`Warm incoming air`,`Prevent food from entering the trachea during swallowing`,`Produce mucus in the lungs`,`Filter dust from the air`], ans:1, exp:`The epiglottis is a flap of tissue that folds over the trachea during swallowing to keep food out of the airway.` },
      { q:`Alveoli are surrounded by a dense network of:`, ch:[`Capillaries`,`Nerves only`,`Muscle fibers`,`Bone`], ans:0, exp:`A rich network of tiny capillaries surrounds each alveolus, allowing efficient gas exchange with the blood.` },
      { q:`Why do alveoli have very thin walls and a large total surface area?`, ch:[`To store extra air for later use`,`To maximize efficient gas exchange`,`To help produce sound for speech`,`To filter bacteria out of the blood`], ans:1, exp:`Thin walls and a huge combined surface area let oxygen and carbon dioxide diffuse quickly between air and blood.` },
      { q:`Which of these organs is NOT part of the respiratory system?`, ch:[`Trachea`,`Alveoli`,`Esophagus`,`Bronchi`], ans:2, exp:`The esophagus carries food to the stomach and is part of the digestive system, not the respiratory system.` },
    ]
  },
  { id:'hl16', cat:'Life Sciences', title:`The Nervous System Basics`, diff:'Medium', qs:[
      { q:`The basic functional cell of the nervous system is called a:`, ch:[`Neuron`,`Nephron`,`Osteocyte`,`Myocyte`], ans:0, exp:`Neurons are specialized cells that transmit electrical and chemical signals throughout the nervous system.` },
      { q:`The brain and spinal cord together make up the:`, ch:[`Peripheral nervous system`,`Central nervous system`,`Autonomic nervous system`,`Somatic nervous system`], ans:1, exp:`The central nervous system (CNS) consists of the brain and spinal cord, which process and coordinate information.` },
      { q:`The network of nerves connecting the CNS to the rest of the body is called the:`, ch:[`Central nervous system`,`Peripheral nervous system`,`Skeletal system`,`Endocrine system`], ans:1, exp:`The peripheral nervous system (PNS) includes all the nerves outside the brain and spinal cord.` },
      { q:`The tiny gap between two neurons where signals are chemically transmitted is called a:`, ch:[`Synapse`,`Axon`,`Dendrite`,`Nucleus`], ans:0, exp:`At a synapse, an electrical signal triggers the release of chemicals that carry the signal to the next neuron.` },
      { q:`Chemical messengers that carry signals across a synapse are called:`, ch:[`Hormones`,`Neurotransmitters`,`Enzymes`,`Antibodies`], ans:1, exp:`Neurotransmitters are released by one neuron and bind to receptors on the next, passing along the signal.` },
      { q:`Which part of a neuron receives incoming signals from other neurons?`, ch:[`Axon`,`Dendrites`,`Myelin sheath`,`Cell body only`], ans:1, exp:`Dendrites are branch-like extensions that receive signals from neighboring neurons.` },
      { q:`Which part of a neuron sends signals away toward other cells?`, ch:[`Dendrites`,`Nucleus`,`Axon`,`Synapse`], ans:2, exp:`The axon is a long fiber that carries electrical signals away from the cell body toward other cells.` },
      { q:`The fatty coating that speeds up signal transmission along many axons is called the:`, ch:[`Synapse`,`Myelin sheath`,`Neurotransmitter`,`Dendrite`], ans:1, exp:`Myelin insulates the axon and allows nerve signals to travel much faster along it.` },
      { q:`A reflex, like quickly pulling your hand away from something hot, is controlled mainly by the:`, ch:[`Cerebrum, after careful thought`,`Spinal cord, without first involving the brain`,`Endocrine system`,`Skeletal system`], ans:1, exp:`Reflexes are processed quickly through the spinal cord, allowing a fast response before the brain even registers the pain.` },
      { q:`Which part of the brain mainly coordinates balance and muscle movement?`, ch:[`Cerebrum`,`Cerebellum`,`Medulla`,`Spinal cord`], ans:1, exp:`The cerebellum fine-tunes movement and helps maintain balance and coordination.` },
      { q:`Which part of the brain controls higher thinking, memory, and voluntary movement?`, ch:[`Cerebellum`,`Cerebrum`,`Brainstem`,`Spinal cord`], ans:1, exp:`The cerebrum is the largest part of the brain and handles thought, memory, and conscious muscle control.` },
      { q:`Sensory neurons mainly function to:`, ch:[`Carry signals from sense organs to the central nervous system`,`Carry signals from the brain to muscles only`,`Store long-term memories`,`Produce hormones`], ans:0, exp:`Sensory neurons detect information like light, sound, or touch and send it toward the brain and spinal cord.` },
    ]
  },
  { id:'hl17', cat:'Life Sciences', title:`The Skeletal & Muscular Systems`, diff:'Easy', qs:[
      { q:`Approximately how many bones are in the adult human skeleton?`, ch:[`106`,`206`,`306`,`406`], ans:1, exp:`The adult human skeleton typically has 206 bones, though babies are born with more that fuse together over time.` },
      { q:`The place where two or more bones meet is called a:`, ch:[`Ligament`,`Tendon`,`Joint`,`Cartilage`], ans:2, exp:`Joints are the connection points between bones, and many allow the skeleton to move.` },
      { q:`Connective tissue that attaches muscle to bone is called a:`, ch:[`Ligament`,`Tendon`,`Cartilage`,`Nerve`], ans:1, exp:`Tendons are tough, fibrous tissues that connect muscles to the bones they move.` },
      { q:`Connective tissue that connects bone to bone at a joint is called a:`, ch:[`Tendon`,`Ligament`,`Neuron`,`Villus`], ans:1, exp:`Ligaments hold bones together at joints and help stabilize movement.` },
      { q:`Which type of muscle is attached to bones and is under voluntary control?`, ch:[`Cardiac muscle`,`Smooth muscle`,`Skeletal muscle`,`Involuntary muscle`], ans:2, exp:`Skeletal muscles are attached to bones by tendons and can be consciously controlled, such as when you move your arm.` },
      { q:`Which type of muscle makes up the heart and works involuntarily?`, ch:[`Skeletal muscle`,`Cardiac muscle`,`Smooth muscle`,`Voluntary muscle`], ans:1, exp:`Cardiac muscle is found only in the heart and contracts automatically without conscious control.` },
      { q:`Which type of muscle lines organs like the stomach and intestines and works involuntarily?`, ch:[`Skeletal muscle`,`Cardiac muscle`,`Smooth muscle`,`Voluntary muscle`], ans:2, exp:`Smooth muscle lines internal organs and blood vessels, contracting automatically to move materials through the body.` },
      { q:`Bones produce blood cells within their:`, ch:[`Cartilage`,`Bone marrow`,`Periosteum`,`Joints`], ans:1, exp:`Red bone marrow, found inside certain bones, is where most new blood cells are produced.` },
      { q:`Which type of joint, found at the knee and elbow, allows movement mainly in one direction like a door hinge?`, ch:[`Ball-and-socket joint`,`Hinge joint`,`Pivot joint`,`Fixed joint`], ans:1, exp:`Hinge joints allow back-and-forth motion in a single plane, much like a door swinging on its hinge.` },
      { q:`Muscles typically work in pairs across a joint because a single muscle can only:`, ch:[`Push, not pull`,`Pull (contract), not push`,`Grow, not shrink`,`Rotate, not bend`], ans:1, exp:`Muscles can only actively contract to pull; a paired muscle is needed to move the joint back the other way.` },
      { q:`Which of these is NOT a function of the skeletal system?`, ch:[`Supporting the body`,`Protecting internal organs`,`Producing blood cells`,`Digesting food`], ans:3, exp:`Digesting food is a job of the digestive system, not the skeletal system, which supports, protects, and produces blood cells.` },
      { q:`Cartilage differs from bone mainly in that cartilage is:`, ch:[`Harder and more brittle`,`Softer and more flexible`,`Made of muscle tissue`,`Found only in the brain`], ans:1, exp:`Cartilage is a flexible connective tissue that cushions joints and is softer than rigid bone.` },
    ]
  },
  { id:'hl18', cat:'Life Sciences', title:`Microorganisms: Bacteria, Viruses & Fungi`, diff:'Easy', qs:[
      { q:`Bacteria are classified as which type of cell?`, ch:[`Eukaryotic`,`Prokaryotic`,`Viral`,`Fungal`], ans:1, exp:`Bacteria are prokaryotes, meaning their cells lack a nucleus and other membrane-bound organelles.` },
      { q:`Are viruses generally considered living organisms by most biologists?`, ch:[`Yes, they meet all the criteria for life`,`No, because they cannot reproduce without a host cell`,`Yes, but only in water`,`No, because they are too large`], ans:1, exp:`Viruses cannot carry out life processes like reproduction on their own; they must hijack a host cell's machinery.` },
      { q:`Which structure protects many bacterial cells and lies just outside the cell membrane?`, ch:[`Nucleus`,`Cell wall`,`Chloroplast`,`Mitochondria`], ans:1, exp:`Most bacteria have a rigid cell wall that provides shape and protection.` },
      { q:`Antibiotics are used to treat infections caused by:`, ch:[`Viruses`,`Bacteria`,`All microorganisms equally`,`Only fungi`], ans:1, exp:`Antibiotics target structures and processes found in bacteria, such as their cell walls, to kill or stop them.` },
      { q:`Antibiotics are NOT effective against which type of pathogen?`, ch:[`Bacteria`,`Viruses`,`All bacteria and viruses`,`None; antibiotics work on everything`], ans:1, exp:`Viruses do not have the cellular structures that antibiotics target, so antibiotics cannot cure viral infections.` },
      { q:`Which of these is an example of a beneficial use of bacteria?`, ch:[`Causing all human diseases`,`Helping make foods like yogurt and cheese`,`Destroying entire ecosystems`,`Living only in extreme environments`], ans:1, exp:`Certain bacteria ferment milk to produce foods like yogurt and cheese, showing bacteria can be helpful, not just harmful.` },
      { q:`Viruses reproduce by:`, ch:[`Dividing on their own like bacteria`,`Invading a host cell and using its machinery to make copies`,`Absorbing nutrients from soil`,`Photosynthesizing`], ans:1, exp:`A virus injects its genetic material into a host cell, forcing the cell to produce new virus particles.` },
      { q:`Fungi, such as mushrooms and molds, get nutrients by:`, ch:[`Photosynthesizing like plants`,`Absorbing nutrients from their environment, often from decomposing matter`,`Hunting and eating prey`,`Making their own food from sunlight`], ans:1, exp:`Fungi release enzymes onto their food source and absorb the broken-down nutrients, often from dead organic material.` },
      { q:`Which kingdom do fungi belong to, separate from plants and animals?`, ch:[`Kingdom Plantae`,`Kingdom Animalia`,`Kingdom Fungi`,`Kingdom Protista`], ans:2, exp:`Fungi have their own kingdom because they differ from plants and animals in how they get nutrients and in their cell structure.` },
      { q:`Yeast, used in baking and brewing, is an example of a:`, ch:[`Bacterium`,`Virus`,`Fungus`,`Protist`], ans:2, exp:`Yeast is a single-celled fungus that ferments sugars, producing carbon dioxide that makes bread rise.` },
      { q:`Vaccines work mainly by:`, ch:[`Killing all bacteria in the body`,`Training the immune system to recognize a pathogen before a real infection occurs`,`Directly destroying viruses on contact`,`Replacing damaged cells`], ans:1, exp:`Vaccines expose the immune system to a harmless piece or weakened form of a pathogen, so it can respond quickly if it encounters the real one later.` },
      { q:`Which of these is NOT a typical characteristic of bacteria?`, ch:[`Lacking a true nucleus`,`Having a cell wall`,`Being single-celled`,`Having a true, membrane-bound nucleus`], ans:3, exp:`Bacteria are prokaryotes and do not have a true, membrane-bound nucleus, unlike eukaryotic cells.` },
    ]
  },
];
